  if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();if(this.editing){this.editing=false;this.managerRows();}else this.close();return true;}
  if(this.kind==='manager'&&!this.editing&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter'].includes(e.key)){
   e.preventDefault();e.stopImmediatePropagation();const rows=[...this.panel.querySelectorAll<HTMLElement>('.cm-waypoint-row')];if(!rows.length)return true;
   let i=Math.max(0,rows.findIndex(row=>row.dataset.number===this.managerNumber));
   if(e.key==='Enter'){this.nav.call(this.canvas,rows[i].dataset.number!);return true;}
   i=(i+(['ArrowUp','ArrowLeft'].includes(e.key)?-1:1)+rows.length)%rows.length;
   this.managerNumber=rows[i].dataset.number!;this.paintManager();rows[i].scrollIntoView({block:'nearest'});return true;
  }
