   e.preventDefault();e.stopImmediatePropagation();if(this.kind==='picker'){this.pickerKey?.(e);return true;}
   const items=[...this.panel.querySelectorAll<HTMLButtonElement>('.cm-chip,.cm-chips .cm-icon')];let i=Math.max(0,items.findIndex(el=>el.classList.contains('is-key-selected')));
   if(e.key==='Enter'){items[i]?.click();return true;}
   if(e.key==='ArrowUp'||e.key==='ArrowDown'){const r=items[i].getBoundingClientRect(),down=e.key==='ArrowDown';const candidates=items.map((el,index)=>({el,index,r:el.getBoundingClientRect()})).filter(v=>down?v.r.top>r.top+4:v.r.top<r.top-4).sort((a,b)=>Math.abs(a.r.top-r.top)-Math.abs(b.r.top-r.top)||Math.abs(a.r.left-r.left)-Math.abs(b.r.left-r.left));if(candidates[0])i=candidates[0].index;
   }else i=(i+((e.key==='ArrowLeft'||(e.key==='Tab'&&e.shiftKey))?-1:1)+items.length)%items.length;
